import os, json, urllib.request, urllib.error
from pathlib import Path
for line in Path('/workspace/.env').read_text().splitlines():
    line=line.strip()
    if not line or line.startswith('#') or '=' not in line:
        continue
    k,v=line.split('=',1)
    os.environ.setdefault(k.strip(), v.strip().strip('"').strip("'"))
key = os.environ.get('API_KEY') or os.environ.get('ANTHROPIC_API_KEY')

def call(url, method="GET", body=None):
    data = None if body is None else json.dumps(body).encode()
    req = urllib.request.Request(
        url, data=data, method=method,
        headers={
            "content-type": "application/json",
            "x-api-key": key,
            "anthropic-version": "2023-06-01",
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            raw = resp.read().decode()
            return resp.status, raw
    except urllib.error.HTTPError as e:
        err = e.read().decode(errors="replace")
        if key and key in err:
            err = err.replace(key, "[redacted]")
        return e.code, err

code, raw = call("https://api.anthropic.com/v1/models")
print("MODELS_HTTP", code)
try:
    data = json.loads(raw)
    ids = [m.get("id") for m in data.get("data", [])]
    print("MODEL_COUNT", len(ids))
    print("MODELS", ", ".join(ids[:30]))
except Exception:
    print(raw[:500])

# try a couple likely models if list failed
candidates = []
try:
    data = json.loads(raw)
    candidates = [m.get("id") for m in data.get("data", []) if m.get("id")]
except Exception:
    candidates = ["claude-sonnet-4-5", "claude-3-5-haiku-20241022", "claude-3-haiku-20240307"]

if candidates:
    mid = candidates[0]
    code, raw = call("https://api.anthropic.com/v1/messages", "POST", {
        "model": mid,
        "max_tokens": 16,
        "messages": [{"role":"user","content":"Reply with the single word pong."}]
    })
    print("CHAT_HTTP", code, "MODEL", mid)
    try:
        data = json.loads(raw)
        if "error" in data:
            print("CHAT_ERROR", data["error"].get("type"), data["error"].get("message","")[:200])
        else:
            text=""
            for b in data.get("content") or []:
                if isinstance(b, dict) and b.get("type")=="text":
                    text += b.get("text","")
            print("CHAT_TEXT", text[:120])
            print("CHAT_STOP", data.get("stop_reason"))
    except Exception:
        print(raw[:400])
